def esc(s): return html.escape(s)
def logo(): return '<div class="wordmark"><svg viewBox="0 0 24 28" width="19" aria-hidden="true"><path fill="#01dc82" d="M17 28H0L2 10c1-1 2-1 4-1L7 0h16l1 3-2 16c-1 2-2 2-4 2z"/><path fill="#033330" d="M9 5l-.5 5H14l-.4 5h5l.7-8c-.4-1.2-1-1.7-2.4-2zM5.5 21l.6-7h5l-.4 4.5h5l-.5 4.5H7c-1-.3-1.2-.8-1.5-2z"/></svg><span>Buildn</span></div>'
CSS='''<style>:root{--brand:#01dc82;--deep:#033330;--lime:#cfe66a;--red:#b3261e;--amber:#9a6700;--ink:#0f172a;--muted:#475569;--line:#e2e8f0;--bg:#fafaf9;--card:#fff;--serif:"Newsreader",Georgia,serif;--sans:"Plus Jakarta Sans",system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);line-height:1.55}main{max-width:70rem;margin:auto;padding:3rem 1.5rem 5rem}.wordmark{display:flex;align-items:center;gap:.55rem;font-weight:700;color:var(--deep)}header{margin-bottom:2rem}h1,h2,h3{font-family:var(--serif);color:var(--deep)}h1{font-size:2.25rem;line-height:1.1;margin:.8rem 0 .4rem}h2{font-size:1.4rem;margin:0 0 .4rem}h3{font-size:1.08rem;margin:.1rem 0 .35rem}p{margin:.42rem 0 .8rem}a{color:#087c54}.date,.facts{font:.78rem ui-monospace,SFMono-Regular,monospace;color:var(--muted)}.card{background:var(--card);border:1px solid var(--line);border-radius:.8rem;padding:1.35rem;margin:1.1rem 0}.badges{display:flex;gap:.45rem;flex-wrap:wrap;margin-bottom:.7rem}.badge{font-size:.67rem;text-transform:uppercase;letter-spacing:.07em;font-weight:700;padding:.16rem .48rem;border-radius:.35rem;background:#e2e8f0;color:#334155}.good{background:#dcfce7;color:#166534}.warn{background:#fef3c7;color:#854d0e}.diagram{margin:1rem 0;border:1px solid var(--line);border-radius:.55rem;padding:.8rem;background:#fff}.diagram svg{display:block;width:100%;height:auto}.label{font:600 10px var(--sans);letter-spacing:.06em;fill:#475569}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem}.matrix{width:100%;border-collapse:collapse;font-size:.83rem}.matrix th,.matrix td{border-bottom:1px solid var(--line);padding:.55rem;text-align:left;vertical-align:top}.matrix th{color:var(--deep)}.callout{border-left:3px solid var(--amber);background:#fffbeb;color:#713f12;padding:.65rem .85rem;border-radius:.25rem;font-size:.9rem}.wins{margin:.45rem 0;padding-left:1.1rem}.wins li{margin:.14rem 0}.top{border-left-color:var(--brand);background:#f0fdf4;color:#14532d}.overview-link{font-size:.86rem}</style>'''
def head(title): return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Newsreader:opsz,wght@6..72,400;6..72,600&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap" rel="stylesheet">{CSS}</head><body><main>'
def signal_svg(words):
 x=[24,172,320,468]; boxes=''.join(f'<rect x="{x[i]}" y="58" width="118" height="46" rx="7" fill="#fff" stroke="#cbd5e1"/><text x="{x[i]+59}" y="84" text-anchor="middle" class="label">{esc(w)}</text>' for i,w in enumerate(words))
 arrows=''.join(f'<path d="M{x[i]+118} 81H{x[i+1]-10}" stroke="#94a3b8" fill="none" marker-end="url(#a)"/>' for i in range(3))
 return f'<div class="diagram"><svg viewBox="0 0 610 160" role="img" aria-label="Signal map"><defs><marker id="a" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0 0L6 3L0 6z" fill="#94a3b8"/></marker></defs><text x="24" y="28" class="label">DAY’S SIGNAL MAP</text>{arrows}{boxes}<path d="M83 104v28h444" stroke="#01dc82" fill="none"/><text x="305" y="149" text-anchor="middle" class="label">bounded pilot → measured decision</text></svg></div>'
def report(l):
 cards=''.join(f'''<article class="card"><div class="badges"><span class="badge good">{typ}</span><span class="badge">direct source</span></div><h2><a href="{esc(l['sources'][i]['url'])}">{esc(name)}</a></h2><p><strong>What:</strong> {esc(what)}</p><p><strong>Why now:</strong> {esc(why)}</p><p><strong>Use:</strong> {esc(use)}</p><div class="callout"><strong>Caveat:</strong> {esc(caveat)}</div><p><strong>Next:</strong> {esc(action)}</p></article>''' for i,(name,typ,what,why,use,caveat,action) in enumerate(l['cards']))
 sources=''.join(f'<li><a href="{esc(s["url"])}">{esc(s["title"])}</a> <span class="facts">— {s["published_or_updated"]}</span></li>' for s in l['sources'])
 return head(f"Daily Ingest Dossier — {l['title']} — {DATE}")+f'''<header>{logo()}<h1>Daily Ingest Dossier — {esc(l['title'])}</h1><div class="date">{DATE} · adaptive lane</div><p>{esc(l['readout'])}</p><p class="overview-link"><a href="daily-ingest-overview-20260730.html">← today’s overview</a></p></header><section><article class="card"><h2>Signal map</h2>{signal_svg(l['signal'])}<p>{esc(l['rationale'])}</p></article>{cards}<article class="card"><h2>Use-case matrix</h2><table class="matrix"><tr><th>Theme</th><th>Buildn OS</th><th>Client work</th><th>Agent workflow</th><th>Personal leverage</th></tr><tr><td>Bounded pilot</td><td>Instrumented, reversible</td><td>Small approved scope</td><td>Named inputs and outputs</td><td>Low-risk trial</td></tr><tr><td>Evidence</td><td>Traceable artifact</td><td>Reviewable outcome</td><td>Logs and owner</td><td>Reusable decision note</td></tr><tr><td>Control</td><td>Policy and rollback</td><td>Consent and access</td><td>Least privilege</td><td>Manual fallback</td></tr></table></article><article class="card"><h2>Top actions</h2><ul class="wins"><li>Open the primary release</li><li>Choose one bounded workflow</li><li>Define success and rollback</li><li>Measure before expanding</li></ul></article><article class="card"><h2>Source trail</h2><ul class="wins">{sources}</ul></article></section></main></body></html>'''

ledger={'date':DATE,'generated_at':STAMP,'editorial_thesis':'Use newly native agent interfaces to make client-facing intelligence more grounded, code review more context-aware, and interactive assistance more measurable.','topic_groups':[{k:v for k,v in l.items() if k in ('slug','title','rationale','sources')} | {'selection_rationale':l['rationale']} for l in lanes]}
