for g in ledger['topic_groups']: g.pop('rationale',None)
(ROOT/'daily-ingest-20260730.json').write_text(json.dumps(ledger,indent=2)+'\n')
for l in lanes: (ROOT/f"daily-ingest-{l['slug']}-20260730.html").write_text(report(l))
links=''.join(f'<article class="card"><div class="badges"><span class="badge good">selected lane</span></div><h2><a href="daily-ingest-{l["slug"]}-20260730.html">{esc(l["title"])}</a></h2><p>{esc(l["rationale"])}</p></article>' for l in lanes)
top=''.join(f'<li><strong>{esc(l["cards"][0][0])}</strong> — {esc(l["cards"][0][6])}</li>' for l in lanes)
overview=head(f'Daily Ingest Dossier — Overview — {DATE}')+f'''<header>{logo()}<h1>Daily Ingest Dossier</h1><div class="date">{DATE} · three adaptive lanes</div><p>Today’s thesis: use newly native agent interfaces to make client-facing intelligence more grounded, code review more context-aware, and interactive assistance more measurable.</p></header><section><article class="card"><h2>Editorial map</h2>{signal_svg(['Grounded retrieval','Code review','Realtime interface','Measured rollout'])}<p>Fresh primary releases earned three deliberately distinct lanes. Each is a practical integration or control surface; none requires a speculative platform rewrite.</p></article><div class="grid">{links}</div><article class="card"><h2>All-lanes top three</h2><ol class="wins">{top}</ol><div class="callout top">Recommendation: start with a source-citing retrieval pilot; it creates reusable evidence for the other two lanes.</div></article></section></main></body></html>'''
(ROOT/'daily-ingest-overview-20260730.html').write_text(overview)
# update coverage memory without overwriting historical runs
coverage_path=PAGES/'topic-coverage.json'; cov=json.loads(coverage_path.read_text())
summary=cov.setdefault('rolling_theme_summary',{})
items=cov.setdefault('item_history',[])
for l in lanes:
 key=l['slug']; prev=summary.get(key,{})
 summary[key]={'title':l['title'],'times_covered':prev.get('times_covered',0)+1,'last_covered':DATE}
 for s in l['sources']: items.append({'date':DATE,'theme':key,'title':s['title'],'url':s['url'],'source_type':s['source_type'],'selection_rationale':s['why_selected']})
# retain at least 45 days (all existing recent history is retained)
cov['updated_at']=STAMP
coverage_path.write_text(json.dumps(cov,indent=2)+'\n')
print('generated',len(lanes),'lane reports')
